# ==============================================================================# 089_COMMERCIAL_NORMALIZATION_ENGINE.py## IOTEC COMMERCIAL NORMALIZATION ENGINE## Missão:# Converter registros brutos do Data Lake para o modelo interno do IOTEC.## Não remove duplicados.# Não calcula score.# Não qualifica.# Apenas normaliza.# ==============================================================================from __future__ import annotationsimport sqlite3import jsonimport hashlibimport uuidfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class CommercialNormalizationEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_normalized_company(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            company_uuid TEXT,            lake_id TEXT,            dataset_id TEXT,            provider TEXT,            source_hash TEXT,            company_name TEXT,            document TEXT,            segment TEXT,            city TEXT,            state TEXT,            country TEXT,            phone TEXT,            email TEXT,            website TEXT,            confidence REAL,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _sha(self, obj):        raw = json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def normalize_latest_dataset(self):        lake = self.conn.execute("""            SELECT *            FROM commercial_data_lake            ORDER BY id DESC            LIMIT 1        """).fetchone()        if lake is None:            raise RuntimeError("Data Lake vazio.")        raw = self.conn.execute("""            SELECT *            FROM commercial_raw_dataset            WHERE dataset_id=?        """, (lake["dataset_id"],)).fetchone()        if raw is None:            raise RuntimeError("Dataset bruto não encontrado.")        registros = json.loads(raw["raw_payload"])        total = 0        for item in registros:            company = {                "timestamp": datetime.utcnow().isoformat(),                "company_uuid": str(uuid.uuid4()),                "lake_id": lake["lake_id"],                "dataset_id": raw["dataset_id"],                "provider": raw["provider"],                "source_hash": hashlib.sha256(                    json.dumps(                        item,                        ensure_ascii=False,                        sort_keys=True                    ).encode()                ).hexdigest(),                "company_name": item.get("company")                                or item.get("empresa")                                or item.get("company_name")                                or "",                "document": item.get("cnpj")                            or item.get("document")                            or "",                "segment": item.get("segment")                           or item.get("segmento")                           or "",                "city": item.get("city")                        or item.get("cidade")                        or "",                "state": item.get("state")                         or item.get("estado")                         or "",                "country": item.get("country", "Brasil"),                "phone": item.get("phone", ""),                "email": item.get("email", ""),                "website": item.get("website", ""),                "confidence": 1.0,                "metadata": {                    "origin": "089_COMMERCIAL_NORMALIZATION_ENGINE"                }            }            assinatura = self._sha(company)            self.conn.execute("""            INSERT INTO commercial_normalized_company(                timestamp,                company_uuid,                lake_id,                dataset_id,                provider,                source_hash,                company_name,                document,                segment,                city,                state,                country,                phone,                email,                website,                confidence,                metadata,                hash            )            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)            """,(                company["timestamp"],                company["company_uuid"],                company["lake_id"],                company["dataset_id"],                company["provider"],                company["source_hash"],                company["company_name"],                company["document"],                company["segment"],                company["city"],                company["state"],                company["country"],                company["phone"],                company["email"],                company["website"],                company["confidence"],                json.dumps(company["metadata"], ensure_ascii=False),                assinatura            ))            total += 1        self.conn.commit()        return total# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = CommercialNormalizationEngine()    total = engine.normalize_latest_dataset()    print("=" * 80)    print("COMMERCIAL NORMALIZATION")    print("=" * 80)    print(f"Empresas normalizadas : {total}")    print("Status                : SUCCESS")    print("=" * 80)